1	import React, { useEffect, useRef, useState } from 'react';
2	import MessageBubble from './MessageBubble';
3	import TypingIndicator from './TypingIndicator';
4	import SafetyBanner from './SafetyBanner';
5	import WelcomeBackBanner from './WelcomeBackBanner';
6	import EmptyState from './EmptyState';
7	import './MessageThread.css';
8	
9	/**
10	 * MessageThread -- Scrollable message list with auto-scroll.
11	 * Handles empty state, welcome-back banners, safety banners, and typing indicator.
12	 *
13	 * @param {{
14	 *   messages: Array,
15	 *   isTyping: boolean,
16	 *   isConnected: boolean,
17	 *   welcomeBack: object|null,
18	 *   dismissWelcomeBack: () => void,
19	 *   onSendMessage: (text:string) => void,
20	 *   onArtifactTap: (type:string, data:any) => void,
21	 *   onLongPress: (message:object) => void,
22	 *   activeSafetyAlert: object|null,
23	 *   onSafetyAction: () => void,
24	 *   onSafetyDismiss: () => void,
25	 *   isViewingPast: boolean,
26	 * }} props
27	 */
28	function MessageThread({
29	  messages,
30	  isTyping,
31	  isConnected,
32	  welcomeBack,
33	  dismissWelcomeBack,
34	  onSendMessage,
35	  onArtifactTap,
36	  onLongPress,
37	  activeSafetyAlert,
38	  onSafetyAction,
39	  onSafetyDismiss,
40	  isViewingPast,
41	  onRate,
42	  onPractice,
43	}) {
44	  const bottomRef = useRef(null);
45	  const [slowResponse, setSlowResponse] = useState(false);
46	  const slowTimerRef = useRef(null);
47	
48	  // Auto-scroll to bottom on new messages or typing changes
49	  useEffect(() => {
50	    if (bottomRef.current) {
51	      bottomRef.current.scrollIntoView({ behavior: 'smooth' });
52	    }
53	  }, [messages, isTyping]);
54	
55	  // AI response timeout: show "taking longer than usual" after 30s of typing
56	  useEffect(() => {
57	    if (isTyping) {
58	      slowTimerRef.current = setTimeout(() => {
59	        setSlowResponse(true);
60	      }, 30000);
61	    } else {
62	      queueMicrotask(() => setSlowResponse(false));
63	      if (slowTimerRef.current) {
64	        clearTimeout(slowTimerRef.current);
65	        slowTimerRef.current = null;
66	      }
67	    }
68	    return () => {
69	      if (slowTimerRef.current) {
70	        clearTimeout(slowTimerRef.current);
71	      }
72	    };
73	  }, [isTyping]);
74	
75	  // Dismiss welcome-back when user sends first message
76	  useEffect(() => {
77	    if (messages.length > 0 && welcomeBack) {
78	      const hasUserMsg = messages.some((m) => m.role === 'user');
79	      if (hasUserMsg) dismissWelcomeBack();
80	    }
81	  }, [messages, welcomeBack, dismissWelcomeBack]);
82	
83	  const isEmpty = messages.length === 0 && !welcomeBack;
84	
85	  return (
86	    <div className="pcp-thread" role="log" aria-live="polite" aria-label="Chat messages">
87	      {/* Safety banner: sticky at top of thread */}
88	      {activeSafetyAlert && (
89	        <SafetyBanner
90	          alert={activeSafetyAlert}
91	          onAction={onSafetyAction}
92	          onDismiss={onSafetyDismiss}
93	        />
94	      )}
95	
96	      <div className="pcp-thread__inner">
97	        {/* Connection banner */}
98	        {!isConnected && !isViewingPast && (
99	          <div className="pcp-thread__connection" role="alert" aria-live="assertive">
100	            Connection lost. Trying to reconnect...
101	          </div>
102	        )}
103	
104	        {/* Welcome-back banner: scrolls with thread, not sticky */}
105	        {!isViewingPast && (
106	          <WelcomeBackBanner
107	            welcomeData={welcomeBack}
108	            onSendMessage={onSendMessage}
109	            onDismiss={dismissWelcomeBack}
110	          />
111	        )}
112	
113	        {/* Empty state */}
114	        {isEmpty && !isViewingPast && (
115	          <EmptyState onSendMessage={onSendMessage} onPractice={onPractice} />
116	        )}
117	
118	        {isEmpty && isViewingPast && (
119	          <div className="pcp-thread__readonly">
120	            This conversation has no messages.
121	          </div>
122	        )}
123	
124	        {/* Spacer to push messages to bottom when thread is short */}
125	        {!isEmpty && <div className="pcp-thread__spacer" />}
126	
127	        {/* Messages */}
128	        {messages.map((msg) => (
129	          <MessageBubble
130	            key={msg.id}
131	            message={msg}
132	            onArtifactTap={onArtifactTap}
133	            onLongPress={onLongPress}
134	            onSendMessage={onSendMessage}
135	            onRate={onRate}
136	          />
137	        ))}
138	
139	        {/* Typing indicator */}
140	        {!isViewingPast && isTyping && <TypingIndicator />}
141	
142	        {/* Slow response warning (>30s) */}
143	        {!isViewingPast && slowResponse && (
144	          <div className="pcp-thread__slow-response" role="status" aria-live="polite">
145	            PC Pal is taking longer than usual. Please wait...
146	          </div>
147	        )}
148	
149	        <div ref={bottomRef} aria-hidden="true" />
150	      </div>
151	    </div>
152	  );
153	}
154	
155	export default MessageThread;

