        <GuideStuckSheet
          guideTitle={guide.title}
          stepNumber={currentStep + 1}
          stepTitle={step.title || step.body || step.text}
          onClose={handleStuckClose}
          onSendMessage={onSendMessage}
        />
      )}
    </div>
  );
}

